/// The node's `with` clause: the only hosts this node may reach.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host from an http(s) URL. Returns None if the URL is not
/// well-formed enough to name a host.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    // Drop any userinfo ("user:pass@host").
    let host_port = authority.rsplit('@').next()?;
    // Drop any port.
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS
            .iter()
            .any(|allowed| host.eq_ignore_ascii_case(allowed)),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Refuse out-of-scope hosts locally. The host would otherwise trap
            // the whole run; here one bad subscription is recorded as a failure.
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in node allowlist".into(),
                });
                continue;
            }

            // Transport failures come back as values; one dead feed does not
            // fail the tick.
            match crate::aap::caps::http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
